/* TabNext + D360 Quiz
 *
 * Plays the question bank generated by export-to-blog.js in the assessment
 * project. Seven answer styles, four ways in, and a citation on every question.
 *
 * Two things worth knowing before changing anything in here.
 *
 * 1. The marking section is a deliberate line-by-line port of grade.js, the
 *    marker that scores the written papers. If the two disagree, the same
 *    answer scores differently on the blog and on paper. assets/quiz/marking-
 *    cases.json holds fixtures generated by the real marker, and quiz-test.html
 *    asserts this file agrees with every one of them. Run that page after
 *    touching anything below the "marking" heading.
 *
 * 2. Nothing anywhere uses drag. Ordering and matching are tap-driven, which is
 *    the only thing that works with a thumb and gives keyboard support without
 *    a second implementation.
 */
(function () {
  'use strict';

  var SCHEMA = 1;
  var DOC_URL = 'https://help.salesforce.com/s/articleView?id=';
  var BEST_KEY = 'tnq-best-v1';
  var DAILY_KEY = 'tnq-daily-v1';

  // =====================================================================
  // marking - a port of grade.js. Keep in step with it.
  // =====================================================================

  function normTerm(s) {
    return String(s)
      .toLowerCase()
      .replace(/[‘’]/g, "'")
      .replace(/[“”]/g, '"')
      .trim()
      .replace(/^[\s"'(\[]+|[\s"')\].,;:!?]+$/g, '')
      .replace(/[-‐-―\/]+/g, ' ')
      .replace(/\s+/g, ' ')
      .replace(/(\w)s$/, '$1');
  }

  function normOption(s) {
    return String(s).trim().replace(/\s+/g, ' ').toLowerCase();
  }

  function toNumber(v) {
    var n = parseFloat(String(v).replace(/,/g, '').replace(/[^0-9.\-]/g, ''));
    return isFinite(n) ? n : null;
  }

  function resolveOption(resp, options) {
    var s = String(resp).trim();
    var direct = null;
    for (var i = 0; i < options.length; i++) {
      if (normOption(options[i]) === normOption(s)) { direct = options[i]; break; }
    }
    if (direct) return direct;
    if (/^[a-z]$/i.test(s)) {
      var idx = s.toLowerCase().charCodeAt(0) - 97;
      if (idx >= 0 && idx < options.length) return options[idx];
    }
    if (/^\d+$/.test(s)) {
      var n = parseInt(s, 10);
      if (n >= 0 && n < options.length) return options[n];
      if (n - 1 >= 0 && n - 1 < options.length) return options[n - 1];
    }
    return null;
  }

  function mark(item, resp, usePartial) {
    var opts = item.options || [];
    var ans = item.answer || [];

    var missing = resp === undefined || resp === null || resp === '' ||
      (Array.isArray(resp) && !resp.length);
    if (missing) return { score: 0, correct: false, answered: false, note: 'no response' };

    switch (item.type) {
      case 'single': {
        var picked = resolveOption(Array.isArray(resp) ? resp[0] : resp, opts);
        if (!picked) return { score: 0, correct: false, answered: true, note: 'response matched no option' };
        var ok = normOption(picked) === normOption(ans[0]);
        return { score: ok ? 1 : 0, correct: ok, answered: true, given: picked };
      }

      case 'multi': {
        var list = (Array.isArray(resp) ? resp : [resp])
          .map(function (r) { return resolveOption(r, opts); })
          .filter(Boolean);
        var keyed = {}, keyedCount = 0;
        ans.forEach(function (a) { if (!keyed[normOption(a)]) { keyed[normOption(a)] = true; keyedCount++; } });
        var seen = {};
        list.forEach(function (g) { seen[normOption(g)] = true; });
        var hits = 0, wrong = 0;
        Object.keys(seen).forEach(function (g) { if (keyed[g]) hits++; else wrong++; });
        var exact = hits === keyedCount && wrong === 0;
        if (exact) return { score: 1, correct: true, answered: true, given: list };
        if (!usePartial) return { score: 0, correct: false, answered: true, given: list, note: hits + '/' + keyedCount + ' correct, ' + wrong + ' wrong' };
        return { score: Math.max(0, (hits - wrong) / keyedCount), correct: false, answered: true, given: list };
      }

      case 'tf': {
        var v = typeof resp === 'boolean' ? resp : /^(true|t|yes|y)$/i.test(String(resp).trim());
        var keyedTf = /^true$/i.test(ans[0]);
        return { score: v === keyedTf ? 1 : 0, correct: v === keyedTf, answered: true, given: v };
      }

      case 'numeric': {
        var n = toNumber(resp);
        if (n === null) return { score: 0, correct: false, answered: true, note: 'response is not a number' };
        var target = toNumber(ans[0]);
        var tol = typeof item.tolerance === 'number' ? item.tolerance : 0;
        var near = Math.abs(n - target) <= tol;
        return { score: near ? 1 : 0, correct: near, answered: true, given: n };
      }

      case 'term': {
        var r = normTerm(resp);
        var hit = ans.some(function (a) { return normTerm(a) === r; });
        return { score: hit ? 1 : 0, correct: hit, answered: true, given: String(resp).trim() };
      }

      case 'order': {
        var seq = (Array.isArray(resp) ? resp : String(resp).split(/\s*(?:,|->|>)\s*/))
          .map(function (r) { return resolveOption(r, opts); })
          .filter(Boolean);
        var right = ans.filter(function (a, i) {
          return seq[i] && normOption(seq[i]) === normOption(a);
        }).length;
        var allRight = right === ans.length && seq.length === ans.length;
        if (allRight) return { score: 1, correct: true, answered: true, given: seq };
        if (!usePartial) return { score: 0, correct: false, answered: true, given: seq, note: right + '/' + ans.length + ' positions right' };
        return { score: right / ans.length, correct: false, answered: true, given: seq };
      }

      case 'match': {
        var pairs = item.pairs || [];
        var given = {};
        if (Array.isArray(resp)) {
          resp.forEach(function (s) {
            var bits = String(s).split('::');
            if (bits[0] && bits[1]) given[normOption(bits[0])] = normOption(bits[1]);
          });
        } else if (typeof resp === 'object') {
          Object.keys(resp).forEach(function (l) { given[normOption(l)] = normOption(resp[l]); });
        }
        var got = pairs.filter(function (p) {
          return given[normOption(p.left)] === normOption(p.right);
        }).length;
        var full = got === pairs.length;
        if (full) return { score: 1, correct: true, answered: true };
        if (!usePartial) return { score: 0, correct: false, answered: true, note: got + '/' + pairs.length + ' pairs right' };
        return { score: got / pairs.length, correct: false, answered: true };
      }

      default:
        return { score: 0, correct: false, answered: true, note: 'unknown item type "' + item.type + '"' };
    }
  }

  // Exposed so quiz-test.html can check this file against the fixtures without
  // starting a quiz.
  window.tnqMarking = { mark: mark, normTerm: normTerm, normOption: normOption, toNumber: toNumber };

  // =====================================================================
  // odds and ends
  // =====================================================================

  function mulberry32(a) {
    return function () {
      a |= 0; a = (a + 0x6d2b79f5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function seedFrom(text) {
    var h = 2166136261;
    for (var i = 0; i < text.length; i++) {
      h ^= text.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  }

  function shuffle(list, rnd) {
    var r = rnd || Math.random;
    for (var i = list.length - 1; i > 0; i--) {
      var j = Math.floor(r() * (i + 1));
      var t = list[i]; list[i] = list[j]; list[j] = t;
    }
    return list;
  }

  function esc(text) {
    return String(text === undefined || text === null ? '' : text).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  }

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function store(key, value) {
    try {
      if (value === undefined) {
        var raw = window.localStorage.getItem(key);
        return raw ? JSON.parse(raw) : null;
      }
      window.localStorage.setItem(key, JSON.stringify(value));
    } catch (e) { /* private browsing, or storage full */ }
    return null;
  }

  function todayKey() {
    return new Date().toISOString().slice(0, 10);
  }

  // =====================================================================
  // drawing a set of questions
  // =====================================================================

  /* Two items can each be sound and still spoil each other: a term item's
   * answer, or a numeric item's figure, sometimes appears in another item's
   * stem or rationale. Individually fine, together a giveaway. The written
   * papers have had to catch these by hand, which does not scale. */
  function leaks(candidate, chosen) {
    function answersOf(it) {
      if (it.type !== 'term' && it.type !== 'numeric') return [];
      return (it.answer || []).map(function (a) { return String(a).toLowerCase().trim(); })
        .filter(function (a) { return a.length > 3; });
    }
    function textOf(it) {
      return (it.stem + ' ' + (it.options || []).join(' ') + ' ' + (it.rationale || '')).toLowerCase();
    }
    var candAnswers = answersOf(candidate);
    var candText = textOf(candidate);
    for (var i = 0; i < chosen.length; i++) {
      var other = chosen[i];
      var otherText = textOf(other);
      for (var a = 0; a < candAnswers.length; a++) {
        if (otherText.indexOf(candAnswers[a]) !== -1) return true;
      }
      var otherAnswers = answersOf(other);
      for (var b = 0; b < otherAnswers.length; b++) {
        if (candText.indexOf(otherAnswers[b]) !== -1) return true;
      }
    }
    return false;
  }

  function take(pool, want, chosen, rnd) {
    var out = [];
    var list = shuffle(pool.slice(), rnd);
    for (var i = 0; i < list.length && out.length < want; i++) {
      if (chosen.indexOf(list[i]) !== -1) continue;
      if (leaks(list[i], chosen.concat(out))) continue;
      out.push(list[i]);
    }
    return out;
  }

  function drawPaper(spec, items, rnd) {
    var pool = items.slice();

    if (spec.only_buried) pool = pool.filter(function (i) { return i.buried; });
    if (spec.roles && spec.roles.length) {
      pool = pool.filter(function (i) {
        return (i.roles || []).some(function (r) { return spec.roles.indexOf(r) !== -1; });
      });
    }
    if (spec.tiers && spec.tiers.length) {
      pool = pool.filter(function (i) { return spec.tiers.indexOf(i.tier) !== -1; });
    }

    var size = Math.min(spec.size, pool.length);
    var chosen = [];

    var levels = spec.levels && Object.keys(spec.levels).length ? spec.levels : null;
    if (levels) {
      Object.keys(levels).forEach(function (level) {
        var want = Math.round(levels[level] * size);
        var slice = pool.filter(function (i) { return i.level === level; });
        if (spec.prefer_buried) {
          slice = slice.filter(function (i) { return i.buried; })
            .concat(slice.filter(function (i) { return !i.buried; }));
        }
        chosen = chosen.concat(take(slice, want, chosen, rnd));
      });
    }

    if (chosen.length < size) {
      chosen = chosen.concat(take(pool, size - chosen.length, chosen, rnd));
    }

    return shuffle(chosen.slice(0, size), rnd);
  }

  function drawSimple(items, want, rnd, filter) {
    var pool = filter ? items.filter(filter) : items.slice();
    return take(pool, Math.min(want, pool.length), [], rnd);
  }

  // =====================================================================
  // the quiz
  // =====================================================================

  function init(root) {
    if (root.hasAttribute('data-tnq-ready')) return;
    root.setAttribute('data-tnq-ready', '');

    var src = root.getAttribute('data-src') || '/assets/quiz/';
    var defaultRounds = parseInt(root.getAttribute('data-rounds'), 10) || 10;

    var elBoot = root.querySelector('.tnq-boot');
    var elPick = root.querySelector('.tnq-pick');
    var elPlay = root.querySelector('.tnq-play');
    var elEnd = root.querySelector('.tnq-end');

    var manifest = null;
    var items = null;

    var run = null; // the quiz in progress

    // ---------------------------------------------------------- loading

    function getJson(name) {
      return fetch(src + name, { credentials: 'same-origin' }).then(function (r) {
        if (!r.ok) throw new Error(name + ' returned ' + r.status);
        return r.json();
      });
    }

    function boot() {
      getJson('manifest.json').then(function (m) {
        if (m.schema > SCHEMA) {
          throw new Error('the question bank is newer than this page understands');
        }
        manifest = m;
        elBoot.hidden = true;
        showPicker();
      }).catch(function (err) {
        elBoot.textContent = 'The questions could not be loaded (' + err.message + '). A refresh usually fixes it.';
      });
    }

    function needItems() {
      if (items) return Promise.resolve(items);
      return getJson('bank.json').then(function (b) {
        items = (b.items || []).filter(function (i) {
          return ['single', 'multi', 'tf', 'numeric', 'term', 'order', 'match'].indexOf(i.type) !== -1;
        });
        return items;
      });
    }

    // ---------------------------------------------------------- picker

    function showPicker(panel) {
      elPlay.hidden = true;
      elEnd.hidden = true;
      elPick.hidden = false;
      elPick.innerHTML = '';

      var head = el('div', 'tnq-pick-head');
      head.appendChild(el('div', 'tnq-pick-title', 'How much do you know?'));
      head.appendChild(el('div', 'tnq-pick-sub',
        manifest.items + ' questions on Tableau Next, Tableau Semantics and Data 360. Every one cites the page it came from.'));
      elPick.appendChild(head);

      var modes = el('div', 'tnq-modes');

      var quick = function () {
        needItems().then(function (list) {
          start(drawSimple(list, defaultRounds, Math.random), 'Quick ' + defaultRounds, 'quick', quick);
        });
      };
      modes.appendChild(modeButton('Quick ' + defaultRounds, 'A mixed set. No setup, just start.', quick));

      var daily = store(DAILY_KEY);
      var doneToday = daily && daily.date === todayKey();
      modes.appendChild(modeButton(
        'Daily challenge',
        doneToday ? 'Done today: ' + daily.score + ' out of ' + daily.total + '. Back tomorrow.' : 'Ten questions. The same ten for everyone, today only.',
        function () {
          if (doneToday) { showDailyResult(daily); return; }
          needItems().then(function (list) {
            var rnd = mulberry32(seedFrom('tnq-' + todayKey()));
            start(drawSimple(list, 10, rnd), 'Daily challenge', 'daily');
          });
        },
        doneToday ? 'done' : ''
      ));

      modes.appendChild(modeButton('Sit a paper', manifest.papers.length + ' papers, from foundation to the buried facts.', function () {
        showPicker('papers');
      }));

      modes.appendChild(modeButton('Build your own', 'Choose the subjects, the level and how many.', function () {
        showPicker('custom');
      }));

      elPick.appendChild(modes);

      if (panel === 'papers') elPick.appendChild(papersPanel());
      if (panel === 'custom') elPick.appendChild(customPanel());

      elPick.appendChild(footer());
    }

    function modeButton(name, desc, onClick, state) {
      var b = el('button', 'tnq-mode');
      b.type = 'button';
      b.appendChild(el('span', 'tnq-mode-name', name));
      b.appendChild(el('span', state === 'done' ? 'tnq-mode-done' : 'tnq-mode-desc', desc));
      b.addEventListener('click', onClick);
      return b;
    }

    function papersPanel() {
      var wrap = el('div', 'tnq-panel');
      wrap.appendChild(el('div', 'tnq-panel-title', 'Papers'));
      var modes = el('div', 'tnq-modes');
      manifest.papers.forEach(function (spec) {
        modes.appendChild(modeButton(
          spec.title.split(':')[0],
          spec.size + ' questions. ' + spec.audience.split('.')[0] + '.',
          function sit() {
            needItems().then(function (list) {
              start(drawPaper(spec, list, Math.random), spec.title.split(':')[0], 'paper:' + spec.name, sit);
            });
          }
        ));
      });
      wrap.appendChild(modes);
      return wrap;
    }

    function customPanel() {
      var wrap = el('div', 'tnq-panel');
      wrap.appendChild(el('div', 'tnq-panel-title', 'Build your own'));

      var picked = {};
      var areaField = el('div', 'tnq-field');
      var areaLabel = el('label', null, 'Subjects. Leave all off for everything.');
      areaField.appendChild(areaLabel);
      var chips = el('div', 'tnq-chips');
      // Areas holding almost nothing make a frustrating quiz, so they stay out
      // of the picker until the bank fills them in.
      manifest.areas.filter(function (a) { return a.count >= 5; }).forEach(function (area) {
        var chip = el('button', 'tnq-chip');
        chip.type = 'button';
        chip.setAttribute('aria-pressed', 'false');
        chip.innerHTML = esc(area.name.replace(/ in Data 360| \(Tableau Semantics\)/g, '')) +
          '<span class="tnq-chip-count">' + area.count + '</span>';
        chip.addEventListener('click', function () {
          picked[area.code] = !picked[area.code];
          chip.setAttribute('aria-pressed', picked[area.code] ? 'true' : 'false');
        });
        chips.appendChild(chip);
      });
      areaField.appendChild(chips);
      wrap.appendChild(areaField);

      var levelField = el('div', 'tnq-field');
      levelField.appendChild(el('label', null, 'Level'));
      var levelChips = el('div', 'tnq-chips');
      var level = '';
      [{ code: '', label: 'Any' }].concat(manifest.levels.map(function (l) {
        return { code: l.code, label: l.code.charAt(0).toUpperCase() + l.code.slice(1), count: l.count };
      })).forEach(function (opt) {
        var chip = el('button', 'tnq-chip');
        chip.type = 'button';
        chip.setAttribute('aria-pressed', opt.code === '' ? 'true' : 'false');
        chip.textContent = opt.label;
        chip.addEventListener('click', function () {
          level = opt.code;
          Array.prototype.forEach.call(levelChips.children, function (c) { c.setAttribute('aria-pressed', 'false'); });
          chip.setAttribute('aria-pressed', 'true');
        });
        levelChips.appendChild(chip);
      });
      levelField.appendChild(levelChips);
      wrap.appendChild(levelField);

      var lenField = el('div', 'tnq-field');
      lenField.appendChild(el('label', null, 'How many questions'));
      var lenChips = el('div', 'tnq-chips');
      var length = 10;
      [5, 10, 20, 30].forEach(function (n) {
        var chip = el('button', 'tnq-chip');
        chip.type = 'button';
        chip.textContent = String(n);
        chip.setAttribute('aria-pressed', n === 10 ? 'true' : 'false');
        chip.addEventListener('click', function () {
          length = n;
          Array.prototype.forEach.call(lenChips.children, function (c) { c.setAttribute('aria-pressed', 'false'); });
          chip.setAttribute('aria-pressed', 'true');
        });
        lenChips.appendChild(chip);
      });
      lenField.appendChild(lenChips);
      wrap.appendChild(lenField);

      var go = el('button', 'tnq-btn', 'Start');
      go.type = 'button';
      var deal = function () {
        var areas = Object.keys(picked).filter(function (k) { return picked[k]; });
        needItems().then(function (list) {
          var drawn = drawSimple(list, length, Math.random, function (i) {
            if (areas.length && areas.indexOf(i.area) === -1) return false;
            if (level && i.level !== level) return false;
            return true;
          });
          if (!drawn.length) {
            go.insertAdjacentHTML('afterend', '<p class="tnq-note">Nothing matches that combination. Try fewer filters.</p>');
            return;
          }
          start(drawn, 'Your own set', 'custom', deal);
        });
      };
      go.addEventListener('click', deal);
      wrap.appendChild(go);
      return wrap;
    }

    function footer() {
      var f = el('div', 'tnq-foot');
      f.innerHTML = 'Questions built from Salesforce documentation captured ' +
        esc(manifest.corpus_retrieved) + '. ' + manifest.counts.beta +
        ' touch Beta features and are badged. Answers are in the page, so this is practice rather than an exam.';
      return f;
    }

    // ---------------------------------------------------------- playing

    function start(deck, title, key, replay) {
      if (!deck.length) return;
      run = {
        deck: deck, title: title, key: key, replay: replay || null,
        at: 0, score: 0, streak: 0, bestStreak: 0,
        results: [], response: null, locked: false
      };
      elPick.hidden = true;
      elEnd.hidden = true;
      elPlay.hidden = false;
      ask();
    }

    function ask() {
      var item = run.deck[run.at];
      run.response = null;
      run.locked = false;

      elPlay.innerHTML = '';

      var head = el('div', 'tnq-head');
      head.appendChild(el('span', null, 'Question ' + (run.at + 1) + ' of ' + run.deck.length));
      var right = el('span');
      if (run.streak >= 3) {
        right.appendChild(el('span', 'tnq-streak', run.streak + ' in a row '));
      }
      right.appendChild(el('span', null, run.score + ' right'));
      head.appendChild(right);
      elPlay.appendChild(head);

      var bar = el('div', 'tnq-bar');
      var fill = el('span', 'tnq-bar-fill');
      fill.style.width = (run.at / run.deck.length * 100) + '%';
      bar.appendChild(fill);
      elPlay.appendChild(bar);

      if (item.buried || item.beta) {
        var badges = el('div', 'tnq-badges');
        if (item.buried) badges.appendChild(el('span', 'tnq-badge is-buried', 'buried'));
        if (item.beta) badges.appendChild(el('span', 'tnq-badge is-beta', 'beta'));
        elPlay.appendChild(badges);
      }

      elPlay.appendChild(el('div', 'tnq-stem', item.stem));

      var ask = askLine(item);
      if (ask) elPlay.appendChild(el('div', 'tnq-ask', ask));

      var answer = el('div', 'tnq-answer');
      elPlay.appendChild(answer);
      renderInput(item, answer);

      var feedback = el('p', 'tnq-feedback');
      feedback.setAttribute('role', 'status');
      feedback.setAttribute('aria-live', 'polite');
      elPlay.appendChild(feedback);

      var actions = el('div', 'tnq-actions');
      var submit = el('button', 'tnq-btn tnq-submit', 'Check');
      submit.type = 'button';
      submit.disabled = true;
      submit.addEventListener('click', check);
      actions.appendChild(submit);
      actions.appendChild(el('span', 'tnq-hint', hintFor(item)));
      elPlay.appendChild(actions);
    }

    function askLine(item) {
      switch (item.type) {
        case 'multi': return 'Select all that apply. ' + item.answer.length + ' of ' + item.options.length + ' are right.';
        case 'order': return 'Tap them in order. Tap one again to take it back.';
        case 'match': return 'Tap the term that fits each description.';
        case 'term': return 'Type your answer. Spelling is forgiven, wording is not.';
        case 'numeric': return 'Enter a number' + (item.unit ? ' in ' + item.unit : '') + '.';
        default: return '';
      }
    }

    function hintFor(item) {
      if (item.type === 'single') return 'Tip: press 1 to ' + item.options.length;
      if (item.type === 'tf') return 'Tip: press T or F';
      return '';
    }

    function enableSubmit(on) {
      var btn = elPlay.querySelector('.tnq-submit');
      if (btn) btn.disabled = !on;
    }

    // ------------------------------------------------- the seven inputs

    function renderInput(item, host) {
      if (item.type === 'single') return renderChoice(item, host, false);
      if (item.type === 'multi') return renderChoice(item, host, true);
      if (item.type === 'tf') return renderTrueFalse(item, host);
      if (item.type === 'numeric') return renderNumeric(item, host);
      if (item.type === 'term') return renderTerm(item, host);
      if (item.type === 'order') return renderOrder(item, host);
      if (item.type === 'match') return renderMatch(item, host);
    }

    function renderChoice(item, host, many) {
      var opts = el('div', 'tnq-opts');
      var order = shuffle(item.options.slice());
      var picked = [];
      order.forEach(function (text, i) {
        var b = el('button', 'tnq-opt');
        b.type = 'button';
        b.setAttribute('aria-pressed', 'false');
        b.appendChild(el('span', 'tnq-key', String(i + 1)));
        b.appendChild(el('span', null, text));
        b.addEventListener('click', function () {
          if (run.locked) return;
          if (many) {
            var at = picked.indexOf(text);
            if (at === -1) picked.push(text); else picked.splice(at, 1);
            b.setAttribute('aria-pressed', at === -1 ? 'true' : 'false');
            run.response = picked.slice();
            enableSubmit(picked.length > 0);
          } else {
            // One tap answers a single-choice question. Asking for a second tap
            // on Check would be a tax on the commonest question type.
            run.response = text;
            check();
          }
        });
        opts.appendChild(b);
      });
      host.appendChild(opts);
      host._order = order;
    }

    function renderTrueFalse(item, host) {
      var wrap = el('div', 'tnq-tf');
      [['True', 'true'], ['False', 'false']].forEach(function (pair) {
        var b = el('button', 'tnq-opt');
        b.type = 'button';
        b.appendChild(el('span', null, pair[0]));
        b.setAttribute('data-value', pair[1]);
        b.addEventListener('click', function () {
          if (run.locked) return;
          run.response = pair[1];
          check();
        });
        wrap.appendChild(b);
      });
      host.appendChild(wrap);
    }

    function renderNumeric(item, host) {
      var row = el('div', 'tnq-input-row');
      var input = el('input', 'tnq-input');
      input.type = 'text';
      input.setAttribute('inputmode', 'decimal');
      input.setAttribute('autocomplete', 'off');
      input.setAttribute('aria-label', 'Your answer' + (item.unit ? ' in ' + item.unit : ''));
      input.placeholder = 'a number';
      input.addEventListener('input', function () {
        run.response = input.value;
        enableSubmit(input.value.trim() !== '');
      });
      input.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' && input.value.trim() !== '') { e.preventDefault(); check(); }
      });
      row.appendChild(input);
      if (item.unit) row.appendChild(el('span', 'tnq-unit', item.unit));
      host.appendChild(row);
    }

    function renderTerm(item, host) {
      var row = el('div', 'tnq-input-row');
      var input = el('input', 'tnq-input');
      input.type = 'text';
      // Mobile keyboards capitalise and autocorrect by default, which mangles
      // the technical vocabulary these questions are made of.
      input.setAttribute('autocomplete', 'off');
      input.setAttribute('autocapitalize', 'off');
      input.setAttribute('autocorrect', 'off');
      input.setAttribute('spellcheck', 'false');
      input.setAttribute('aria-label', 'Your answer');
      input.placeholder = 'your answer';
      input.addEventListener('input', function () {
        run.response = input.value;
        enableSubmit(input.value.trim() !== '');
      });
      input.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' && input.value.trim() !== '') { e.preventDefault(); check(); }
      });
      row.appendChild(input);
      host.appendChild(row);
    }

    function renderOrder(item, host) {
      var order = shuffle(item.options.slice());
      var chosen = [];

      var slots = el('div', 'tnq-order-slots');
      var pool = el('div', 'tnq-pool');
      host.appendChild(slots);
      host.appendChild(pool);

      function paint() {
        slots.innerHTML = '';
        item.options.forEach(function (_, i) {
          var filled = chosen[i];
          var slot = el(filled ? 'button' : 'div', 'tnq-slot' + (filled ? ' is-filled' : ''));
          if (filled) {
            slot.type = 'button';
            slot.addEventListener('click', function () {
              if (run.locked) return;
              chosen.splice(i, 1);
              paint();
            });
          }
          slot.appendChild(el('span', 'tnq-rank', String(i + 1)));
          slot.appendChild(el('span', null, filled || 'not chosen yet'));
          slots.appendChild(slot);
        });

        pool.innerHTML = '';
        order.forEach(function (text) {
          if (chosen.indexOf(text) !== -1) return;
          var b = el('button', 'tnq-opt');
          b.type = 'button';
          b.appendChild(el('span', 'tnq-key', String(chosen.length + 1)));
          b.appendChild(el('span', null, text));
          b.addEventListener('click', function () {
            if (run.locked) return;
            chosen.push(text);
            paint();
          });
          pool.appendChild(b);
        });

        run.response = chosen.slice();
        enableSubmit(chosen.length === item.options.length);
      }

      paint();
      host._paintOrder = paint;
      host._chosen = function () { return chosen; };
    }

    function renderMatch(item, host) {
      var terms = shuffle(item.pairs.map(function (p) { return p.left; }));
      var rows = shuffle(item.pairs.slice());
      var assigned = {}; // right -> left

      function paint() {
        host.innerHTML = '';
        rows.forEach(function (pair) {
          var row = el('div', 'tnq-match-row');
          row.appendChild(el('div', 'tnq-match-def', pair.right));
          var chips = el('div', 'tnq-chips');
          terms.forEach(function (term) {
            var usedElsewhere = Object.keys(assigned).some(function (r) {
              return assigned[r] === term && r !== pair.right;
            });
            var chip = el('button', 'tnq-chip');
            chip.type = 'button';
            chip.textContent = term;
            chip.setAttribute('aria-pressed', assigned[pair.right] === term ? 'true' : 'false');
            if (usedElsewhere) chip.classList.add('is-faded');
            chip.addEventListener('click', function () {
              if (run.locked) return;
              // A term belongs to one description, so assigning it here takes
              // it away from wherever it was.
              Object.keys(assigned).forEach(function (r) {
                if (assigned[r] === term) delete assigned[r];
              });
              if (assigned[pair.right] === term) delete assigned[pair.right];
              else assigned[pair.right] = term;
              paint();
            });
            chips.appendChild(chip);
          });
          row.appendChild(chips);
          host.appendChild(row);
        });

        var out = {};
        Object.keys(assigned).forEach(function (r) { out[assigned[r]] = r; });
        run.response = out;
        enableSubmit(Object.keys(assigned).length === item.pairs.length);
      }

      paint();
      host._paintMatch = paint;
    }

    // ------------------------------------------------------- marking

    function check() {
      if (run.locked) return;
      run.locked = true;

      var item = run.deck[run.at];
      var result = mark(item, run.response, false);
      var partial = mark(item, run.response, true);

      if (result.correct) {
        run.score++;
        run.streak++;
        if (run.streak > run.bestStreak) run.bestStreak = run.streak;
      } else {
        run.streak = 0;
      }

      run.results.push({
        n: run.at + 1,
        item: item,
        correct: result.correct,
        part: partial.score,
        given: run.response
      });

      showAnswer(item, result, partial);
    }

    function showAnswer(item, result, partial) {
      var answer = elPlay.querySelector('.tnq-answer');

      // freeze and mark up the controls
      Array.prototype.forEach.call(answer.querySelectorAll('button, input'), function (node) {
        node.disabled = true;
      });

      if (item.type === 'single' || item.type === 'multi') {
        Array.prototype.forEach.call(answer.querySelectorAll('.tnq-opt'), function (b) {
          var text = b.lastChild.textContent;
          var isKey = item.answer.some(function (a) { return normOption(a) === normOption(text); });
          var chose = item.type === 'multi'
            ? (run.response || []).indexOf(text) !== -1
            : run.response === text;
          if (isKey && chose) b.classList.add('is-right');
          else if (isKey) b.classList.add('is-missed');
          else if (chose) b.classList.add('is-wrong');
          else b.classList.add('is-faded');
        });
      }

      if (item.type === 'tf') {
        Array.prototype.forEach.call(answer.querySelectorAll('.tnq-opt'), function (b) {
          var v = b.getAttribute('data-value');
          if (v === String(item.answer[0]).toLowerCase()) b.classList.add('is-right');
          else if (v === run.response) b.classList.add('is-wrong');
          else b.classList.add('is-faded');
        });
      }

      if (item.type === 'order') {
        Array.prototype.forEach.call(answer.querySelectorAll('.tnq-slot'), function (slot, i) {
          var text = slot.lastChild.textContent;
          slot.classList.add(normOption(text) === normOption(item.answer[i]) ? 'is-right' : 'is-wrong');
        });
      }

      if (item.type === 'match') {
        Array.prototype.forEach.call(answer.querySelectorAll('.tnq-match-row'), function (row) {
          var def = row.querySelector('.tnq-match-def').textContent;
          var pair = item.pairs.filter(function (p) { return p.right === def; })[0];
          if (!pair) return;
          var gave = (run.response || {});
          var mine = Object.keys(gave).filter(function (l) { return gave[l] === def; })[0];
          var ok = mine && normOption(mine) === normOption(pair.left);
          row.classList.add(ok ? 'is-right' : 'is-wrong');
          if (!ok) {
            var note = el('div', 'tnq-match-answer');
            note.innerHTML = 'Correct term: <b>' + esc(pair.left) + '</b>';
            row.appendChild(note);
          }
        });
      }

      var feedback = elPlay.querySelector('.tnq-feedback');
      if (result.correct) {
        feedback.className = 'tnq-feedback is-right';
        feedback.innerHTML = '<b>' + esc(praise()) + '</b>';
        if (!reducedMotion()) {
          var stem = elPlay.querySelector('.tnq-stem');
          if (stem) { stem.classList.add('tnq-pop'); setTimeout(function () { stem.classList.remove('tnq-pop'); }, 420); }
        }
      } else {
        feedback.className = 'tnq-feedback is-wrong';
        var right = plainAnswer(item);
        var extra = partial.score > 0 && partial.score < 1
          ? ' You had ' + Math.round(partial.score * 100) + '% of it.'
          : '';
        feedback.innerHTML = '<b>Not quite.</b> ' + esc(right) + esc(extra);
      }

      var actions = elPlay.querySelector('.tnq-actions');
      elPlay.insertBefore(citation(item, !result.correct), actions);
      actions.innerHTML = '';
      var next = el('button', 'tnq-btn tnq-next', run.at + 1 >= run.deck.length ? 'See how you did' : 'Next question');
      next.type = 'button';
      next.addEventListener('click', advance);
      actions.appendChild(next);
      next.focus({ preventScroll: true });
    }

    function praise() {
      var lines = ['Correct.', 'That is the one.', 'Spot on.', 'Right again.', 'Yes.'];
      if (run.streak >= 5) return 'Five in a row. Showing off now.';
      return lines[Math.floor(Math.random() * lines.length)];
    }

    function plainAnswer(item) {
      switch (item.type) {
        case 'tf': return 'The answer is ' + (String(item.answer[0]) === 'true' ? 'true' : 'false') + '.';
        case 'numeric': return 'The answer is ' + item.answer[0] + (item.unit ? ' ' + item.unit : '') + '.';
        case 'term': return 'The answer is ' + item.answer[0] + '.';
        case 'multi': return 'The full set is: ' + item.answer.join('; ') + '.';
        case 'order': return 'The order is: ' + item.answer.join(' then ') + '.';
        case 'match': return 'The correct terms are marked above.';
        default: return 'The answer is ' + item.answer[0] + '.';
      }
    }

    /* The citation is the whole point of this quiz. Open by default when you got
     * it wrong, tucked away when you got it right. */
    function citation(item, open) {
      var wrap = el('div', 'tnq-cite' + (open ? ' is-open' : ''));
      var toggle = el('button', 'tnq-cite-toggle');
      toggle.type = 'button';
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      toggle.textContent = open ? 'Hide the documentation' : 'What do the docs say?';

      var body = el('div', 'tnq-cite-body');
      body.hidden = !open;
      body.appendChild(evidenceNode(item));
      var link = el('a', 'tnq-cite-link');
      link.href = DOC_URL + item.evidence_page_id + '.htm&language=en_US&type=5';
      link.target = '_blank';
      link.rel = 'noopener';
      link.textContent = 'Read it on help.salesforce.com';
      body.appendChild(link);
      if (item.rationale) body.appendChild(el('p', 'tnq-why', item.rationale));

      toggle.addEventListener('click', function () {
        body.hidden = !body.hidden;
        toggle.setAttribute('aria-expanded', body.hidden ? 'false' : 'true');
        toggle.textContent = body.hidden ? 'What do the docs say?' : 'Hide the documentation';
        wrap.classList.toggle('is-open', !body.hidden);
      });

      wrap.appendChild(toggle);
      wrap.appendChild(body);
      return wrap;
    }

    /* Plenty of the best facts live in a documentation table. The extraction
     * flattened those rows into the quote, pipes and all, and a flattened row is
     * close to meaningless because the column headings sat on a different line.
     * The export goes back to the source page and ships the real table, so when
     * one is available it is shown instead of the quote, with the rows the item
     * rested on marked. */
    function evidenceNode(item) {
      if (item.evidence_table) return tableNode(item.evidence_table);
      return quoteNode(item.evidence_quote);
    }

    function quoteNode(text) {
      var t = String(text).trim();
      if ((t.match(/\|/g) || []).length >= 2) {
        var cells = t.split('|').map(function (c) { return c.trim(); })
          .filter(function (c) { return c.length; });
        if (cells.length >= 2) {
          var list = el('ul', 'tnq-quote-list');
          cells.forEach(function (c) { list.appendChild(el('li', null, c)); });
          return list;
        }
      }
      return el('p', 'tnq-quote', '“' + t + '”');
    }

    function tableNode(t) {
      var wrap = el('div', 'tnq-table-wrap');
      // An empty top-left heading means the first column labels the rows rather
      // than holding data, which is how most of these tables are built.
      var rowHeaders = !String(t.headers[0] || '').trim();

      var scroller = el('div', 'tnq-table-scroll');
      var table = el('table', 'tnq-table');

      var thead = el('thead');
      var hrow = el('tr');
      t.headers.forEach(function (h) {
        var th = el('th', null, stripMd(h));
        th.scope = 'col';
        hrow.appendChild(th);
      });
      thead.appendChild(hrow);
      table.appendChild(thead);

      var tbody = el('tbody');
      var quoted = t.rows.filter(function (_, i) { return t.hit[i]; }).length;
      // A thirteen-row table is a wall on a phone, so when it is long show the
      // rows the question rested on and keep the rest a tap away.
      var collapse = t.rows.length > 6 && quoted > 0 && quoted < t.rows.length;

      t.rows.forEach(function (cells, i) {
        var tr = el('tr', t.hit[i] ? 'is-quoted' : '');
        if (collapse && !t.hit[i]) tr.classList.add('is-extra');
        cells.forEach(function (c, j) {
          var cell;
          if (j === 0 && rowHeaders) {
            cell = el('th', null, stripMd(c));
            cell.scope = 'row';
          } else {
            cell = el('td', null, stripMd(c));
          }
          // Read out beside the value once the table stacks on a narrow screen.
          cell.setAttribute('data-label', stripMd(t.headers[j] || ''));
          tr.appendChild(cell);
        });
        tbody.appendChild(tr);
      });
      table.appendChild(tbody);
      scroller.appendChild(table);
      wrap.appendChild(scroller);

      if (collapse) {
        var hidden = t.rows.length - quoted;
        var more = el('button', 'tnq-cite-toggle');
        more.type = 'button';
        more.setAttribute('aria-expanded', 'false');
        more.textContent = 'Show the other ' + hidden + ' row' + (hidden === 1 ? '' : 's');
        more.addEventListener('click', function () {
          var open = table.classList.toggle('is-open');
          more.setAttribute('aria-expanded', open ? 'true' : 'false');
          more.textContent = open
            ? 'Hide the other ' + hidden + ' row' + (hidden === 1 ? '' : 's')
            : 'Show the other ' + hidden + ' row' + (hidden === 1 ? '' : 's');
        });
        wrap.appendChild(more);
      }
      return wrap;
    }

    /* Cells arrive as markdown: links, bold, code ticks. The text is what matters
     * here, and rendering the markup would mean trusting documentation source as
     * HTML, which is not a trade worth making for a bit of styling. */
    function stripMd(text) {
      return String(text === undefined || text === null ? '' : text)
        .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
        .replace(/\*\*([^*]+)\*\*/g, '$1')
        .replace(/`([^`]+)`/g, '$1')
        .trim();
    }

    function reducedMotion() {
      return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    }

    function advance() {
      run.at++;
      if (run.at >= run.deck.length) finish();
      else ask();
    }

    // ---------------------------------------------------------- results

    function finish() {
      elPlay.hidden = true;
      elEnd.hidden = false;
      elEnd.innerHTML = '';

      var total = run.deck.length;
      var ratio = run.score / total;

      elEnd.appendChild(scoreBlock(run.score, total, ratio));
      elEnd.appendChild(subScores());
      elEnd.appendChild(areaBreakdown());
      elEnd.appendChild(shareBlock());
      elEnd.appendChild(reviewBlock());

      if (run.key === 'daily') {
        store(DAILY_KEY, { date: todayKey(), score: run.score, total: total, grid: gridString() });
      }

      var actions = el('div', 'tnq-end-actions');
      // The daily challenge is the same ten for everyone, so it gets no second
      // attempt. Everything else deals a fresh set of the same kind.
      var replay = run.replay;
      var canReplay = replay && run.key !== 'daily';
      if (canReplay) {
        var again = el('button', 'tnq-btn', 'Another go');
        again.type = 'button';
        again.addEventListener('click', function () { replay(); });
        actions.appendChild(again);
      }
      var back = el('button', 'tnq-btn tnq-ghost', 'Pick a different set');
      back.type = 'button';
      back.addEventListener('click', function () { showPicker(); });
      actions.appendChild(back);
      elEnd.appendChild(actions);
      again.focus({ preventScroll: true });
    }

    function scoreBlock(score, total, ratio) {
      var wrap = el('div');
      var final = el('div', 'tnq-final');
      final.innerHTML = score + ' <small>out of ' + total + '</small>';
      wrap.appendChild(final);

      var verdict = 'Worth another run at it.';
      if (ratio === 1) verdict = 'Every one. Nothing left to teach you here.';
      else if (ratio >= 0.8) verdict = 'Strong. You have clearly done this for real.';
      else if (ratio >= 0.6) verdict = 'Solid, with a few gaps worth reading up on.';
      else if (ratio >= 0.4) verdict = 'The shape is there. The details are where it went.';
      wrap.appendChild(el('div', 'tnq-verdict', verdict));

      var bests = store(BEST_KEY) || {};
      var prev = bests[run.key];
      if (prev === undefined || ratio > prev) {
        bests[run.key] = ratio;
        store(BEST_KEY, bests);
        if (prev !== undefined) wrap.appendChild(el('div', 'tnq-best', 'A new best for this set.'));
      } else {
        wrap.appendChild(el('div', 'tnq-best', 'Your best on this set: ' + Math.round(prev * 100) + '%.'));
      }
      return wrap;
    }

    function subScores() {
      var wrap = el('div', 'tnq-sub');

      var buried = run.results.filter(function (r) { return r.item.buried; });
      var buriedRight = buried.filter(function (r) { return r.correct; }).length;

      wrap.appendChild(subItem('Streak', run.bestStreak + ' in a row', 'Your longest run'));
      wrap.appendChild(subItem(
        'Buried facts',
        buried.length ? buriedRight + '/' + buried.length : 'none asked',
        'Stated only in a Note or a step'
      ));
      var partial = run.results.reduce(function (t, r) { return t + r.part; }, 0);
      wrap.appendChild(subItem(
        'With part marks',
        Math.round(partial * 10) / 10 + '/' + run.deck.length,
        'Credit for partly right answers'
      ));
      return wrap;
    }

    function subItem(label, value, note) {
      var box = el('div', 'tnq-sub-item');
      box.appendChild(el('div', 'tnq-sub-label', label));
      box.appendChild(el('div', 'tnq-sub-value', value));
      box.appendChild(el('div', 'tnq-sub-note', note));
      return box;
    }

    function areaBreakdown() {
      var wrap = el('div', 'tnq-breakdown');
      wrap.appendChild(el('div', 'tnq-breakdown-title', 'How you did by subject'));

      var byArea = {};
      run.results.forEach(function (r) {
        var a = r.item.area;
        if (!byArea[a]) byArea[a] = { right: 0, total: 0 };
        byArea[a].total++;
        if (r.correct) byArea[a].right++;
      });

      var names = {};
      manifest.areas.forEach(function (a) { names[a.code] = a.name; });

      Object.keys(byArea).sort(function (a, b) {
        return (byArea[b].right / byArea[b].total) - (byArea[a].right / byArea[a].total);
      }).forEach(function (code) {
        var d = byArea[code];
        var row = el('div', 'tnq-row');
        row.appendChild(el('span', 'tnq-row-name', (names[code] || code).replace(/ in Data 360| \(Tableau Semantics\)/g, '')));
        var bar = el('span', 'tnq-row-bar');
        var fill = el('span', 'tnq-row-fill');
        fill.style.width = (d.right / d.total * 100) + '%';
        bar.appendChild(fill);
        row.appendChild(bar);
        row.appendChild(el('span', 'tnq-row-num', d.right + '/' + d.total));
        wrap.appendChild(row);
      });
      return wrap;
    }

    function gridString() {
      return run.results.map(function (r) {
        if (r.correct) return '🟩';
        if (r.part > 0) return '🟨';
        return '🟥';
      }).join('');
    }

    function shareBlock() {
      var wrap = el('div', 'tnq-share');
      var grid = el('div', 'tnq-grid', gridString());
      wrap.appendChild(grid);

      var btn = el('button', 'tnq-btn tnq-ghost', 'Copy result');
      btn.type = 'button';
      btn.addEventListener('click', function () {
        var text = 'TabNext + D360 Quiz — ' + run.title + '\n' +
          run.score + '/' + run.deck.length + '\n' + gridString() + '\n' +
          window.location.href;
        var done = function () {
          var said = wrap.querySelector('.tnq-copied');
          if (!said) { said = el('span', 'tnq-copied', ' Copied.'); wrap.appendChild(said); }
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(done, done);
        } else {
          var ta = document.createElement('textarea');
          ta.value = text; document.body.appendChild(ta); ta.select();
          try { document.execCommand('copy'); } catch (e) { /* nothing to do */ }
          document.body.removeChild(ta);
          done();
        }
      });
      wrap.appendChild(btn);
      return wrap;
    }

    function reviewBlock() {
      var missed = run.results.filter(function (r) { return !r.correct; });
      var wrap = el('div', 'tnq-review');
      if (!missed.length) {
        wrap.appendChild(el('div', 'tnq-review-title', 'Nothing to review'));
        return wrap;
      }
      wrap.appendChild(el('div', 'tnq-review-title', 'Worth a second look'));
      missed.forEach(function (r) {
        var box = el('div', 'tnq-review-item');
        var stem = el('div', 'tnq-review-stem');
        stem.appendChild(el('span', 'tnq-review-num', 'Q' + r.n));
        stem.appendChild(document.createTextNode(r.item.stem));
        box.appendChild(stem);
        var ans = el('div', 'tnq-review-answer');
        ans.innerHTML = '<b>' + esc(plainAnswer(r.item).replace(/^The answer is /, '')) + '</b>';
        box.appendChild(ans);
        box.appendChild(citation(r.item, false));
        wrap.appendChild(box);
      });
      return wrap;
    }

    function showDailyResult(daily) {
      elPick.hidden = true;
      elPlay.hidden = true;
      elEnd.hidden = false;
      elEnd.innerHTML = '';
      var final = el('div', 'tnq-final');
      final.innerHTML = daily.score + ' <small>out of ' + daily.total + '</small>';
      elEnd.appendChild(final);
      elEnd.appendChild(el('div', 'tnq-verdict', 'That was today’s challenge. A fresh ten tomorrow.'));
      if (daily.grid) elEnd.appendChild(el('div', 'tnq-grid', daily.grid));
      var back = el('button', 'tnq-btn', 'Pick something else');
      back.type = 'button';
      back.addEventListener('click', function () { showPicker(); });
      var actions = el('div', 'tnq-end-actions');
      actions.appendChild(back);
      elEnd.appendChild(actions);
    }

    // ---------------------------------------------------------- keyboard

    document.addEventListener('keydown', function (event) {
      if (event.metaKey || event.ctrlKey || event.altKey) return;
      if (elPlay.hidden || !run) return;
      var active = document.activeElement;
      if (active && /^(INPUT|TEXTAREA)$/.test(active.tagName)) return;

      var item = run.deck[run.at];

      if (!run.locked && item.type === 'tf' && /^[tf]$/i.test(event.key)) {
        event.preventDefault();
        var want = event.key.toLowerCase() === 't' ? 'true' : 'false';
        var btn = elPlay.querySelector('.tnq-opt[data-value="' + want + '"]');
        if (btn) btn.click();
        return;
      }

      if (!run.locked && /^[1-9]$/.test(event.key)) {
        var buttons = elPlay.querySelectorAll('.tnq-answer .tnq-opt');
        var pick = parseInt(event.key, 10) - 1;
        if (buttons[pick]) { event.preventDefault(); buttons[pick].click(); }
        return;
      }

      if (run.locked && (event.key === 'Enter' || event.key === ' ')) {
        var next = elPlay.querySelector('.tnq-next');
        if (next && active !== next) { event.preventDefault(); next.click(); }
      }
    });

    // ------------------------------------------------------------- go

    // A quiz partway down a page costs nothing until the reader comes near it.
    if (window.IntersectionObserver) {
      var io = new IntersectionObserver(function (entries) {
        if (entries.some(function (e) { return e.isIntersecting; })) { io.disconnect(); boot(); }
      }, { rootMargin: '400px 0px' });
      io.observe(root);
    } else {
      boot();
    }
  }

  function bootAll() {
    Array.prototype.forEach.call(document.querySelectorAll('[data-tnq]'), init);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootAll);
  else bootAll();
})();
